mapper.select:
SELECT 
FROM (
    SELECT id, display_date, created_at FROM orders WHERE deleted_at IS NULL



                AND (created_at < #{cursor.createdAt} OR created_at IS NULL
                    OR (created_at = #{cursor.createdAt} AND id < #{cursor.id}))


                AND created_at IS NULL AND id < #{cursor.id}



    ORDER BY created_at DESC, id DESC LIMIT #{limit}
) o
LEFT JOIN order_items i ON i.order_id = o.id
ORDER BY o.created_at DESC, o.id DESC, i.line_number
